//! The crates' licence texts (RC-110-72): `resources/licenses/THIRD-PARTY-LICENSES`, generated by
//! `scripts/licenses.sh` beside the list ([`super::licenses`]), compiled in and read once. Every
//! package carries the same file.
//!
//! The file holds each text once: a line `=== Licence ===...`, one line per crate the text covers
//! (`<name> <version> (<licence>): <where it was read>`), a line `--- Text ---...`, the text
//! (`scripts/lib/license_texts.py`, which refuses a text holding either line). The page shows
//! the texts of the crates its filter matches, up to [`SHOWN_BYTES`] at once, so a whole
//! megabyte of licences is never laid out.
//!
//! rCommander's own licence leads them (RC-110-75): the repository's `LICENSE`, which every
//! package carries beside the program, compiled in as [`OWN`] and shown while the filter is empty
//! or matches the name or the licence - "Show licence" on the About tab opens it.

use std::{collections::HashMap, sync::LazyLock};

use super::licenses::matching;

const TEXTS: &str = include_str!("../../../../resources/licenses/THIRD-PARTY-LICENSES");

/// rCommander's own licence text, the GNU GPL version 3 (`LICENSE` at the repository's root).
const OWN_TEXT: &str = include_str!("../../../../../../LICENSE");

/// The line that heads rCommander's own licence text, as the crates' lines head theirs.
const OWN_LINE: &str = concat!(
    "rCommander ",
    env!("CARGO_PKG_VERSION"),
    " (",
    env!("CARGO_PKG_LICENSE"),
    "): LICENSE"
);

/// rCommander's own licence, as one more text.
static OWN: LazyLock<Text> = LazyLock::new(|| Text {
    covers: vec![OWN_LINE],
    body: OWN_TEXT.trim_end_matches('\n'),
});

/// Where a text's block starts and where its crates end, each the start of a line.
const BLOCK: &str = "\n=== Licence ";
const BODY: &str = "\n--- Text ";

/// The most text the page lays out at once; the filter narrows the rest down.
pub const SHOWN_BYTES: usize = 64 * 1024;

/// One licence text and the crates it covers.
#[derive(Debug, PartialEq, Eq)]
pub struct Text {
    /// One line per crate: `<name> <version> (<licence>): <where it was read>`.
    pub covers: Vec<&'static str>,
    pub body: &'static str,
}

/// The texts in the file's order, and per crate (`name`, `version`) the indices of its texts.
struct Index {
    texts: Vec<Text>,
    by_crate: HashMap<(&'static str, &'static str), Vec<usize>>,
}

static INDEX: LazyLock<Index> = LazyLock::new(|| index(parse(TEXTS)));

/// The texts of the crates `filter` matches ([`matching`]), each once, in the file's order, as
/// many as fit [`SHOWN_BYTES`] (at least one); and how many more there are. rCommander's own
/// licence comes first when the filter is empty or matches its name or licence ([`own_matches`]).
pub fn for_filter(filter: &str) -> (Vec<&'static Text>, usize) {
    let index = &*INDEX;
    let own = own_matches(filter).then_some(&*OWN);
    let mut wanted: Vec<usize> = matching(filter)
        .filter_map(|package| {
            index
                .by_crate
                .get(&(package.name.as_str(), package.version.as_str()))
        })
        .flatten()
        .copied()
        .collect();
    wanted.sort_unstable();
    wanted.dedup();
    let mut shown: Vec<&'static Text> = own.into_iter().collect();
    let mut bytes: usize = shown.iter().map(|text| text.body.len()).sum();
    for &at in &wanted {
        let text = &index.texts[at];
        if !shown.is_empty() && bytes + text.body.len() > SHOWN_BYTES {
            break;
        }
        bytes += text.body.len();
        shown.push(text);
    }
    let more = wanted.len() + usize::from(own.is_some()) - shown.len();
    (shown, more)
}

/// Whether `filter` is empty or contained, ignoring case, in rCommander's name or its licence -
/// the rule [`matching`] applies to a crate.
fn own_matches(filter: &str) -> bool {
    let filter = filter.trim().to_lowercase();
    filter.is_empty()
        || "rcommander".contains(&filter)
        || env!("CARGO_PKG_LICENSE").to_lowercase().contains(&filter)
}

/// The blocks of a THIRD-PARTY-LICENSES file; the part before the first is its preamble.
fn parse(file: &'static str) -> Vec<Text> {
    file.split(BLOCK)
        .skip(1)
        .filter_map(|chunk| {
            // The rest of the separator line, then the crates, then the text's own separator.
            let (_, rest) = chunk.split_once('\n')?;
            let (covers, body) = rest.split_once(BODY)?;
            let body = body.split_once('\n').map_or("", |(_, body)| body);
            Some(Text {
                covers: covers.lines().filter(|line| !line.is_empty()).collect(),
                body: body.trim_end_matches('\n'),
            })
        })
        .collect()
}

fn index(texts: Vec<Text>) -> Index {
    let mut by_crate: HashMap<(&'static str, &'static str), Vec<usize>> = HashMap::new();
    for (at, text) in texts.iter().enumerate() {
        for &line in &text.covers {
            let mut words = line.split_whitespace();
            if let (Some(name), Some(version)) = (words.next(), words.next()) {
                let indices = by_crate.entry((name, version)).or_default();
                if indices.last() != Some(&at) {
                    indices.push(at);
                }
            }
        }
    }
    Index { texts, by_crate }
}

